// Package gen provides the embedded OpenAPI specification for the Loan
// Submission API.
//
// The openapi.json file under the openapi/ sub-directory is generated by
// running `make openapi` (uses Redocly CLI to bundle resources/openapi/).
// Regenerate whenever the source YAML specs change.
package gen

import "embed"

// OpenAPISpec is an embedded filesystem containing the bundled OpenAPI JSON.
// It is used at runtime to serve the spec via GET /openapi.json.
//
//go:embed openapi
var OpenAPISpec embed.FS
